'use strict';
(()=>{const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};const tabs=[['music','Music'],['book','Books'],['site','Sites / Preserved web'],['knowledge','Knowledge'],['game','Games'],['playlists','Playlists']];let selected='music';const list=document.getElementById('favorite-items'),search=document.getElementById('favorite-search'),status=document.getElementById('favorite-status');function render(){const personal=window.MAHA_PERSONAL;if(!personal)return;list.replaceChildren();for(const b of document.querySelectorAll('[data-favorite-tab]')){b.classList.toggle('active',b.dataset.favoriteTab===selected);b.setAttribute('aria-pressed',String(b.dataset.favoriteTab===selected));}if(selected==='playlists'){const manage=make('button','Manage playlists','action');manage.onclick=()=>personal.manager();list.append(manage);const matches=[personal.likedSongs(),...personal.state.playlists].filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase()));for(const p of matches){const card=make('article',undefined,'favorite-entry'),link=make('a',p.name);link.href='music.html?playlist='+encodeURIComponent(p.id);link.append(make('small',p.tracks.length+' tracks · Play playlist'));card.append(link);list.append(card);}status.textContent=matches.length+' playlists';return;}if(selected==='music'){const actions=make('div',undefined,'personal-actions'),liked=make('a','Play Liked Songs','action'),shuffle=make('a','Shuffle Liked Songs','action');liked.href='music.html?playlist=liked-songs';shuffle.href='music.html?playlist=liked-songs&shuffle=1';actions.append(liked,shuffle);list.append(actions);}const matches=personal.state.favorites.filter(i=>(selected==='music'?['song','album'].includes(i.kind):i.kind===selected)&&(i.title+' '+i.subtitle).toLowerCase().includes(search.value.toLowerCase()));for(const item of matches){const card=make('article',undefined,'favorite-entry'),link=make('a',item.title);link.href=item.url;link.append(make('small',(item.kind==='album'?'Album · ':item.kind==='song'?'Song · ':'')+item.subtitle));if(item.cover){const image=make('img',undefined,'favorite-artwork');image.src=item.cover;image.alt='';image.loading='lazy';image.onerror=()=>image.remove();card.append(image);}card.append(link,personal.button(item));list.append(card);}status.textContent=matches.length+(matches.length===1?' favorite':' favorites');if(!matches.length)list.append(make('p',selected==='game'?'Games will appear here when the games library is available.':'Save items with the heart button in their library section.'));}
for(const [id,label] of tabs){const button=make('button',label);button.dataset.favoriteTab=id;button.onclick=()=>{selected=id;render();};document.getElementById('favorite-tabs').append(button);}search.oninput=render;window.addEventListener('maha-personal-change',render);window.MAHA_PERSONAL.ready.then(render);
})();
